"""Unified ontology documentation site generator (#440).

Builds a modern, static-site-ready documentation tree under ``ontology-docs/``
from canonical sources. The same ``build_ontology_docs()`` function is reused by
the ``gts-full`` generator to embed an identical copy into the offline snapshot,
so ``gmeow-full.gts`` remains self-contained.

The tree is assembled with MkDocs Material and includes:

* auto-generated landing, slice index, and profile pages from ontology metadata;
* per-term Markdown reference pages (classes, properties, individuals, datatypes);
* an optional WebVOWL diagram;
* an optional OOPS! pitfall report;
* optional WIDOCO-derived provenance/changelog fragments.
"""

from __future__ import annotations

import json
import logging
import os
import shutil
import subprocess
from collections import defaultdict
from pathlib import Path
from typing import TYPE_CHECKING, Any, TypedDict, cast

from rdflib import OWL, RDF, RDFS, Graph, URIRef
from rdflib.namespace import DCTERMS, SKOS

from gmeow_tools.config import (
    FULL_PROFILE_IRI,
    NAMESPACE,
    ONTOLOGY_IRI,
    PROJECT_ROOT,
    SLICES_DIR,
    STATEMENT_RDF12_FILE,
    WIDOCO_IMAGE,
)
from gmeow_tools.docs import profiles_section_html
from gmeow_tools.export import curie
from gmeow_tools.generator import Generator, register, write_text
from gmeow_tools.graph import iter_module_files, load_merged_graph
from gmeow_tools.language_tags import public_text
from gmeow_tools.quality import run_oops
from gmeow_tools.runner import image_available, run_container
from gmeow_tools.slices import Slice, discover_slices

if TYPE_CHECKING:
    from collections.abc import Sequence

#: Brand colours for the MkDocs Material theme.
_BRAND_PRIMARY = "#111214"
_BRAND_BACKGROUND = "#fffdf5"
_BRAND_ACCENT_RED = "#ea4335"
_BRAND_ACCENT_BLUE = "#4285f4"
_BRAND_ACCENT_YELLOW = "#fbbc05"
_BRAND_ACCENT_GREEN = "#34a853"

#: Category subdirectories for per-term reference pages.
_CATEGORY_DIRS: dict[str, str] = {
    "class": "classes",
    "property": "properties",
    "individual": "individuals",
    "datatype": "datatypes",
}

#: Property rdf:type IRI → short kind label.
_PROPERTY_KINDS: dict[URIRef, str] = {
    OWL.ObjectProperty: "object",
    OWL.DatatypeProperty: "datatype",
    OWL.AnnotationProperty: "annotation",
}


class _Term(TypedDict, total=False):
    """A flattened term record for rendering Markdown reference pages."""

    category: str
    iri: str
    curie: str
    filename: str
    label: str
    definition: str
    parents: list[str]
    prop_kind: str
    domain: str
    range: str
    functional: bool
    sub_property_of: list[str]
    types: list[str]


class _WriteContext:
    """Carries the output directory and banner parameters for render helpers.

    *root* is the MkDocs project directory (``ontology-docs/``).
    *docs* is the MkDocs ``docs_dir`` where Markdown source lives.
    """

    def __init__(self, outdir: Path, *, source_hash: str = "") -> None:
        self.root = outdir
        self.docs = outdir / "docs"
        self.docs.mkdir(parents=True, exist_ok=True)
        self.source_hash = source_hash

    def write(self, path: Path, content: str) -> None:
        """Write a generated text file with the GMEOW banner.

        Markdown pages use an HTML-comment banner so MkDocs/preview linters do
        not treat the generated notice as document headings.
        """
        if path.suffix == ".md":
            path.parent.mkdir(parents=True, exist_ok=True)
            banner = (
                "<!-- GENERATED by gmeow ontology-docs -- DO NOT EDIT. -->\n"
                f"<!-- Source hash: {self.source_hash or 'unknown'} -->\n"
                "<!-- https://github.com/Blackcat-Informatics/gmeow-ontology -->\n"
                "\n"
            )
            path.write_text(banner + content, encoding="utf-8")
        else:
            write_text(
                path,
                content,
                name="ontology-docs",
                source_hash=self.source_hash,
            )


def _safe_filename(curie_str: str) -> str:
    """Return a filesystem-safe filename from a CURIE."""
    return f"{curie_str.replace(':', '-')}.md"


def _base_filename(curie_str: str) -> str:
    """Return the base Markdown filename for a CURIE (same as _safe_filename)."""
    return _safe_filename(curie_str)


def _case_fingerprint(local_name: str) -> str:
    """A short, deterministic, case-sensitive fingerprint for a local name.

    Used only when two terms would otherwise collide on case-insensitive
    filesystems.  The fingerprint lists the indices of uppercase characters so
    ``AccountStatus`` and ``accountStatus`` map to different filenames while
    staying readable.
    """
    positions = [str(i) for i, ch in enumerate(local_name) if ch.isupper()]
    return "-".join(positions) if positions else "lower"


def _resolve_filenames(terms: list[_Term]) -> None:
    """Assign unique, case-insensitive-safe filenames to every term record.

    Terms whose base filename would collide (e.g. ``gmeow-AccountStatus`` and
    ``gmeow-accountStatus``) receive a ``-<fingerprint>`` suffix derived from
    the case pattern of the local name.
    """
    from collections import defaultdict

    by_category: dict[str, list[_Term]] = defaultdict(list)
    for term in terms:
        by_category[term["category"]].append(term)

    for _category, members in by_category.items():
        groups: dict[str, list[_Term]] = defaultdict(list)
        for term in members:
            groups[_base_filename(term["curie"]).lower()].append(term)
        for group in groups.values():
            if len(group) == 1:
                group[0]["filename"] = _base_filename(group[0]["curie"])
                continue
            for term in group:
                local = term["curie"].split(":", 1)[1]
                base = _base_filename(term["curie"]).replace(".md", "")
                term["filename"] = f"{base}-{_case_fingerprint(local)}.md"


def ontology_docs_source() -> Path:
    """Write a GMEOW-only graph for documentation and return its path.

    Reuses the same scope policy as ``docs._gmeow_only_source``: only GMEOW's
    own terms are documented; imported gUFO axioms are out of scope.
    """
    from gmeow_tools.config import DIST_DIR

    DIST_DIR.mkdir(parents=True, exist_ok=True)
    out = DIST_DIR / "gmeow-vocab.ttl"
    load_merged_graph(include_imports=False).serialize(destination=out, format="turtle")
    return out


def build_ontology_docs(outdir: Path, *, source_hash: str = "") -> None:
    """Render the complete ontology-docs tree into *outdir*.

    Args:
        outdir: Destination directory (typically ``ontology-docs/``).
        source_hash: Source-hash stamp for generated banners.
    """
    outdir.mkdir(parents=True, exist_ok=True)
    source = ontology_docs_source()
    graph = Graph()
    graph.parse(source, format="turtle")

    ctx = _WriteContext(outdir, source_hash=source_hash)
    terms = _collect_terms(graph)
    _render_landing(ctx, graph, terms)
    _render_slice_pages(ctx)
    _render_profile_pages(ctx)
    _render_reference_pages(ctx, graph, terms)
    _render_mkdocs_config(ctx)

    # Optional stages: skip cleanly when tooling is absent.
    _render_webvowl(ctx, source)
    _render_oops_report(ctx, source)
    _render_widoco_fragments(ctx, source)

    # Build the MkDocs Material HTML site into ontology-docs/site/.
    _build_mkdocs_site(outdir)


def _build_mkdocs_site(outdir: Path) -> None:
    """Run ``mkdocs build`` to produce the HTML site under *outdir*/site/."""
    config = outdir / "mkdocs.yml"
    env = os.environ.copy()
    env["NO_MKDOCS_2_WARNING"] = "true"
    try:
        subprocess.run(
            ["mkdocs", "build", "-f", str(config.name), "-q"],
            check=True,
            cwd=str(config.parent),
            env=env,
        )
    except (subprocess.CalledProcessError, FileNotFoundError) as exc:
        # mkdocs is a runtime dependency; failure here is a build error.
        raise RuntimeError(f"mkdocs build failed for {outdir}: {exc}") from exc

    # MkDocs emits trailing whitespace on many lines; strip it so pre-commit
    # does not need to mutate the committed site tree.
    site_dir = outdir / "site"
    for path in site_dir.rglob("*"):
        if not path.is_file() or path.suffix not in {".html", ".css", ".js"}:
            continue
        try:
            text = path.read_text(encoding="utf-8")
        except UnicodeDecodeError:
            continue
        cleaned = "\n".join(line.rstrip() for line in text.splitlines())
        if text.endswith("\n") and not cleaned.endswith("\n"):
            cleaned += "\n"
        if cleaned != text:
            path.write_text(cleaned, encoding="utf-8")


def _collect_terms(graph: Graph) -> list[_Term]:
    """Collect every GMEOW class, property, individual, and datatype.

    Returns a sorted list of term records suitable for rendering Markdown pages.
    """
    terms: list[_Term] = []

    def in_namespace(node: object) -> bool:
        return isinstance(node, URIRef) and str(node).startswith(NAMESPACE)

    # Classes
    for subject in sorted(graph.subjects(RDF.type, OWL.Class), key=str):
        if not in_namespace(subject):
            continue
        uri = cast(URIRef, subject)
        terms.append(
            _make_term_record(
                graph,
                uri,
                "class",
                parents=sorted(
                    curie(str(o))
                    for o in graph.objects(uri, RDFS.subClassOf)
                    if isinstance(o, URIRef)
                ),
            )
        )

    # Properties
    for ptype, kind in _PROPERTY_KINDS.items():
        for subject in sorted(graph.subjects(RDF.type, ptype), key=str):
            if not in_namespace(subject):
                continue
            uri = cast(URIRef, subject)
            domain_obj = graph.value(uri, RDFS.domain)
            range_obj = graph.value(uri, RDFS.range)
            terms.append(
                _make_term_record(
                    graph,
                    uri,
                    "property",
                    prop_kind=kind,
                    domain=curie(str(domain_obj))
                    if isinstance(domain_obj, URIRef)
                    else "",
                    range=curie(str(range_obj))
                    if isinstance(range_obj, URIRef)
                    else "",
                    functional=OWL.FunctionalProperty in graph.objects(uri, RDF.type),
                    sub_property_of=sorted(
                        curie(str(o))
                        for o in graph.objects(uri, RDFS.subPropertyOf)
                        if isinstance(o, URIRef)
                    ),
                )
            )

    # Individuals
    for subject in sorted(graph.subjects(RDF.type, None), key=str):
        if not in_namespace(subject):
            continue
        uri = cast(URIRef, subject)
        types = sorted(
            curie(str(o))
            for o in graph.objects(uri, RDF.type)
            if isinstance(o, URIRef) and o != OWL.NamedIndividual
        )
        if not types:
            continue
        terms.append(_make_term_record(graph, uri, "individual", types=types))

    # Datatypes
    for subject in sorted(graph.subjects(RDF.type, RDFS.Datatype), key=str):
        if not in_namespace(subject):
            continue
        uri = cast(URIRef, subject)
        terms.append(_make_term_record(graph, uri, "datatype"))

    _resolve_filenames(terms)
    terms.sort(key=lambda t: (t["category"], t["curie"]))
    return terms


def _make_term_record(
    graph: Graph,
    subject: URIRef,
    category: str,
    *,
    parents: list[str] | None = None,
    prop_kind: str = "",
    domain: str = "",
    range: str = "",
    functional: bool = False,
    sub_property_of: list[str] | None = None,
    types: list[str] | None = None,
) -> _Term:
    """Build a term record from a graph subject."""
    term: _Term = {
        "category": category,
        "iri": str(subject),
        "curie": curie(str(subject)),
        "label": public_text(graph, subject, RDFS.label),
        "definition": public_text(graph, subject, SKOS.definition),
    }
    if parents is not None:
        term["parents"] = parents
    if prop_kind:
        term["prop_kind"] = prop_kind
    if domain:
        term["domain"] = domain
    if range:
        term["range"] = range
    if functional:
        term["functional"] = functional
    if sub_property_of is not None:
        term["sub_property_of"] = sub_property_of
    if types is not None:
        term["types"] = types
    return term


def _render_landing(ctx: _WriteContext, graph: Graph, terms: Sequence[_Term]) -> None:
    """Auto-generate ``index.md`` from ontology header + slice metadata."""
    onto = URIRef(ONTOLOGY_IRI)
    title = public_text(graph, onto, DCTERMS.title) or "GMEOW"
    description = public_text(graph, onto, DCTERMS.description)
    version = public_text(graph, onto, OWL.versionInfo) or ""
    creator = public_text(graph, onto, DCTERMS.creator)
    publisher = public_text(graph, onto, DCTERMS.publisher)
    license_obj = graph.value(onto, DCTERMS.license)
    created = public_text(graph, onto, DCTERMS.created)
    modified = public_text(graph, onto, DCTERMS.modified)

    slices = discover_slices()
    core_n = sum(1 for s in slices.values() if s.is_core)
    ext_n = len(slices) - core_n

    profiles = sorted({p for s in slices.values() for p in s.profiles})

    n_classes = sum(1 for t in terms if t["category"] == "class")
    n_properties = sum(1 for t in terms if t["category"] == "property")
    n_individuals = sum(1 for t in terms if t["category"] == "individual")
    n_datatypes = sum(1 for t in terms if t["category"] == "datatype")

    lines = [
        f"# {title}",
        "",
        f"**Version:** `{version}`  ",
        f"**Namespace:** <{NAMESPACE}>  ",
        f"**Terms:** {n_classes} classes, {n_properties} properties, "
        f"{n_individuals} individuals, {n_datatypes} datatypes",
        "",
    ]

    if description:
        lines.extend([description, ""])

    if creator:
        lines.append(f"**Creator:** {creator}  ")
    if publisher:
        lines.append(f"**Publisher:** {publisher}  ")
    if created:
        lines.append(f"**Created:** {created}  ")
    if modified:
        lines.append(f"**Modified:** {modified}  ")
    if isinstance(license_obj, URIRef):
        lines.append(f"**License:** <{license_obj}>  ")
    if lines[-1].startswith("**"):
        lines.append("")

    lines.extend(
        [
            "## Profiles",
            "",
            f"- **Core profile:** <{ONTOLOGY_IRI}> — {core_n} core slices.",
            f"- **Full profile:** <{FULL_PROFILE_IRI}> — "
            f"core plus {ext_n} extension slices.",
        ]
    )
    if profiles:
        lines.append("")
        lines.append("### Named profiles")
        lines.append("")
        for profile in profiles:
            lines.append(f"- [{profile}](profiles/{_safe_filename(profile)})")
    lines.append("")

    lines.extend(
        [
            "## Slices",
            "",
            f"GMEOW is organised into [{len(slices)} slices](slices/index.md): "
            f"{core_n} core and {ext_n} extension. Each slice declares its tier, "
            "dependencies, profiles, and consumer in its manifest.",
            "",
            "## Reference",
            "",
            "Browse the ontology terms by category:",
            "",
            f"- [{n_classes} classes](reference/classes/index.md)",
            f"- [{n_properties} properties](reference/properties/index.md)",
            f"- [{n_individuals} individuals](reference/individuals/index.md)",
            f"- [{n_datatypes} datatypes](reference/datatypes/index.md)",
            "",
        ]
    )

    # Embed the existing Profiles composition HTML as a raw block for parity
    # with the old pyLODE landing page (#330).
    lines.extend(
        [
            "## Composition",
            "",
            "```html",
            profiles_section_html(),
            "```",
            "",
        ]
    )

    ctx.write(ctx.docs / "index.md", "\n".join(lines))


def _render_slice_pages(ctx: _WriteContext) -> None:
    """Auto-generate ``slices/index.md`` and per-slice detail pages."""
    slices = discover_slices()
    slices_dir = ctx.docs / "slices"
    slices_dir.mkdir(parents=True, exist_ok=True)

    profile_groups: dict[str, list[Slice]] = defaultdict(list)
    for s in sorted(slices.values(), key=lambda x: x.name):
        for profile in s.profiles or ("uncategorised",):
            profile_groups[profile].append(s)

    # Main slice index
    lines = [
        "# Slices",
        "",
        "GMEOW is composed of self-contained slices. Each slice's manifest is the "
        "sole source of its identity, tier, dependencies, and consumer.",
        "",
        "| Slice | Tier | Profiles | Dependencies | Consumer |",
        "|---|---|---|---|---|",
    ]
    for s in sorted(slices.values(), key=lambda x: x.name):
        profiles = ", ".join(sorted(s.profiles)) or "—"
        deps = (
            ", ".join(curie(d).replace("gmeow:slices/", "") for d in s.depends_on)
            or "—"
        )
        consumer = " ".join(s.consumers) or "—"
        lines.append(
            f"| [{s.name}]({s.name}.md) | {s.tier} | {profiles} | {deps} | {consumer} |"
        )
    lines.append("")

    if profile_groups:
        lines.extend(
            [
                "## Profiles",
                "",
                "Slices grouped by declared profile:",
                "",
            ]
        )
        for profile in sorted(profile_groups):
            lines.append(
                f"- [{profile}]({_safe_filename(profile).replace('.md', '')}/index.md)"
            )
        lines.append("")

    ctx.write(slices_dir / "index.md", "\n".join(lines))

    # Per-slice detail pages
    for s in sorted(slices.values(), key=lambda x: x.name):
        page = [
            f"# {s.title or s.name}",
            "",
            f"**IRI:** <{s.iri}>  ",
            f"**Tier:** {s.tier}  ",
            f"**Group:** {s.group}  ",
        ]
        if s.creators:
            page.append(f"**Creator:** {', '.join(s.creators)}  ")
        if s.consumers:
            page.append(f"**Consumer:** {' '.join(s.consumers)}  ")
        page.append("")
        if s.depends_on:
            page.extend(
                [
                    "## Dependencies",
                    "",
                    *[f"- <{d}>" for d in s.depends_on],
                    "",
                ]
            )
        if s.profiles:
            page.extend(
                [
                    "## Profiles",
                    "",
                    *[f"- {p}" for p in sorted(s.profiles)],
                    "",
                ]
            )
        ctx.write(slices_dir / f"{s.name}.md", "\n".join(page))

    # Per-profile group pages
    for profile, members in profile_groups.items():
        profile_dir = slices_dir / _safe_filename(profile).replace(".md", "")
        profile_dir.mkdir(parents=True, exist_ok=True)
        page = [
            f"# {profile} slices",
            "",
            f"Slices that declare the `{profile}` profile:",
            "",
        ]
        for s in sorted(members, key=lambda x: x.name):
            page.append(f"- [{s.name}](../{s.name}.md) — {s.title or s.name}")
        page.append("")
        ctx.write(profile_dir / "index.md", "\n".join(page))


def _render_profile_pages(ctx: _WriteContext) -> None:
    """Auto-generate ``profiles/<name>.md`` composition pages."""
    slices = discover_slices()
    profiles_dir = ctx.docs / "profiles"
    profiles_dir.mkdir(parents=True, exist_ok=True)

    profile_members: dict[str, list[Slice]] = defaultdict(list)
    for s in slices.values():
        for profile in s.profiles or ():
            profile_members[profile].append(s)

    if not profile_members:
        ctx.write(
            profiles_dir / "index.md",
            "# Profiles\n\nNo named profiles are declared in the slice manifests.\n",
        )
        return

    index_lines = [
        "# Profiles",
        "",
        "Named profiles aggregate slices that declare a common ``gmeow:sliceProfile``.",
        "",
    ]
    for profile in sorted(profile_members):
        members = profile_members[profile]
        index_lines.append(
            f"- [{profile}]({_safe_filename(profile)}) — {len(members)} slice(s)"
        )
        page = [
            f"# {profile} profile",
            "",
            f"This profile contains {len(members)} slice(s):",
            "",
        ]
        for s in sorted(members, key=lambda x: x.name):
            page.append(
                f"- [{s.name}](../slices/{s.name}.md) — {s.title or s.name} ({s.tier})"
            )
        page.append("")
        ctx.write(profiles_dir / _safe_filename(profile), "\n".join(page))
    index_lines.append("")
    ctx.write(profiles_dir / "index.md", "\n".join(index_lines))


def _render_reference_pages(
    ctx: _WriteContext, graph: Graph, terms: Sequence[_Term]
) -> None:
    """Generate per-term Markdown reference pages."""
    ref_dir = ctx.docs / "reference"
    by_category: dict[str, list[_Term]] = defaultdict(list)
    for term in terms:
        by_category[term["category"]].append(term)

    for category, dir_name in _CATEGORY_DIRS.items():
        cat_dir = ref_dir / dir_name
        cat_dir.mkdir(parents=True, exist_ok=True)
        members = by_category.get(category, [])

        # Category index
        index_lines = [
            f"# {category.capitalize()}s",
            "",
            f"{len(members)} term(s).",
            "",
        ]
        for term in members:
            label = term["label"] or term["curie"]
            index_lines.append(f"- [{label}]({term['filename']}) (`{term['curie']}`)")
        index_lines.append("")
        ctx.write(cat_dir / "index.md", "\n".join(index_lines))

        # Per-term pages
        for term in members:
            page = [f"# {term['label'] or term['curie']}", ""]
            if term["definition"]:
                page.extend([term["definition"], ""])
            page.extend(
                [
                    f"**IRI:** <{term['iri']}>  ",
                    f"**CURIE:** `{term['curie']}`  ",
                    "",
                ]
            )
            if category == "class" and term.get("parents"):
                page.append(
                    "**Subclass of:** "
                    + ", ".join(f"`{p}`" for p in term["parents"])
                    + "  "
                )
                page.append("")
            elif category == "property":
                prop_kind = term.get("prop_kind", "")
                meta = [f"*{prop_kind} property*"] if prop_kind else []
                if term.get("domain"):
                    meta.append(f"domain `{term['domain']}`")
                if term.get("range"):
                    meta.append(f"range `{term['range']}`")
                if term.get("functional"):
                    meta.append("functional")
                if meta:
                    page.append(" · ".join(meta) + "  ")
                    page.append("")
                if term.get("sub_property_of"):
                    page.append(
                        "**Sub-property of:** "
                        + ", ".join(f"`{p}`" for p in term["sub_property_of"])
                        + "  "
                    )
                    page.append("")
            elif category == "individual" and term.get("types"):
                page.append(
                    "**Type:** " + ", ".join(f"`{t}`" for t in term["types"]) + "  "
                )
                page.append("")

            comment = public_text(graph, URIRef(term["iri"]), RDFS.comment)
            if comment:
                page.extend([comment, ""])
            defined_by = graph.value(URIRef(term["iri"]), RDFS.isDefinedBy)
            if isinstance(defined_by, URIRef):
                page.append(f"**Defined by:** <{defined_by}>  ")
                page.append("")

            ctx.write(cat_dir / term["filename"], "\n".join(page))


def _render_mkdocs_config(ctx: _WriteContext) -> None:
    """Write ``mkdocs.yml`` with GMEOW brand colours and local navigation."""
    assets_dir = ctx.docs / "assets"
    assets_dir.mkdir(parents=True, exist_ok=True)
    logo_source = PROJECT_ROOT / "docs" / "gmeow-logo.svg"
    logo_dest = assets_dir / "logo.svg"
    if logo_source.exists():
        shutil.copy(logo_source, logo_dest)

    nav = [
        "docs_dir: docs",
        "site_dir: site",
        "",
        "nav:",
        "  - Home: index.md",
        "  - Reference:",
        "      - Classes: reference/classes/index.md",
        "      - Properties: reference/properties/index.md",
        "      - Individuals: reference/individuals/index.md",
        "      - Datatypes: reference/datatypes/index.md",
        "  - Slices: slices/index.md",
        "  - Profiles: profiles/index.md",
        "  - Visualization: visualization/index.md",
        "  - Quality: quality/oops-report.md",
        "  - About: about.md",
        "  - Changelog: changelog.md",
        "",
        "site_name: GMEOW Ontology Documentation",
        "site_author: Blackcat Informatics Inc.",
        "site_description: >",
        "  Global Metadata and Entity Ontology for the Web",
        "",
        "theme:",
        "  name: material",
        "  logo: assets/logo.svg",
        "  font: false",
        "  palette:",
        "    - scheme: default",
        "      primary: custom",
        "      accent: custom",
        "",
        "extra_css:",
        "  - stylesheets/extra.css",
        "",
        "plugins:",
        "  - search",
        "",
        "markdown_extensions:",
        "  - tables",
        "  - toc:",
        "      permalink: true",
        "",
    ]
    ctx.write(ctx.root / "mkdocs.yml", "\n".join(nav))

    css_dir = ctx.docs / "stylesheets"
    css_dir.mkdir(parents=True, exist_ok=True)
    css = f""":root {{
  --md-primary-fg-color: {_BRAND_PRIMARY};
  --md-primary-bg-color: {_BRAND_BACKGROUND};
  --md-accent-fg-color: {_BRAND_ACCENT_RED};
}}
"""
    ctx.write(css_dir / "extra.css", css)


def _container_path(path: Path) -> str:
    """Return the ``/work/...`` path seen by Docker for a host *path*.

    Relative paths are resolved against the current working directory; the
    result must live under ``PROJECT_ROOT`` because that is what the
    container mounts at ``/work``.
    """
    abs_path = path.resolve()
    return f"/work/{abs_path.relative_to(PROJECT_ROOT).as_posix()}"


def _canonicalize_webvowl_json(path: Path, source: Path) -> None:
    """Rewrite the WebVOWL ontology JSON with deterministic IDs and ordering.

    OWL2VOWL (inside WIDOCO) assigns numeric IDs based on Java collection
    iteration order and emits duplicate nodes for reused terms, so the raw
    output is nondeterministic. We deduplicate by semantic descriptor, renumber
    from a stable order, and sort every list so the committed artifact is
    reproducible.
    """
    data = json.loads(path.read_text(encoding="utf-8"))

    class_attr_by_id = {item["id"]: item for item in data["classAttribute"]}
    prop_attr_by_id = {item["id"]: item for item in data["propertyAttribute"]}

    def _class_descriptor(oid: str, seen: set[str] | None = None) -> tuple[object, ...]:
        if seen is None:
            seen = set()
        if oid in seen:
            return ("cycle",)
        seen = seen | {oid}
        attr = class_attr_by_id[oid]
        if "iri" in attr:
            return ("iri", attr["iri"])
        parts: list[object] = [attr.get("type", "")]
        if "union" in attr:
            members = [_class_descriptor(mid, seen) for mid in attr["union"]]
            parts.append(("union", tuple(sorted(members))))
        label = attr.get("label", {})
        if isinstance(label, dict):
            parts.append(tuple(sorted(label.items())))
        return ("anon", tuple(parts))

    def _prop_descriptor(pid: str, seen: set[str] | None = None) -> tuple[object, ...]:
        if seen is None:
            seen = set()
        attr = prop_attr_by_id[pid]
        if "iri" in attr:
            dom = _class_descriptor(attr["domain"], seen) if "domain" in attr else ("",)
            rng = _class_descriptor(attr["range"], seen) if "range" in attr else ("",)
            return ("iri", attr["iri"], dom, rng)
        parts: list[object] = [attr.get("type", "")]
        if "domain" in attr:
            parts.append(_class_descriptor(attr["domain"], seen))
        if "range" in attr:
            parts.append(_class_descriptor(attr["range"], seen))
        parts.append(tuple(sorted(attr.get("attributes", []))))
        return ("anon", tuple(parts))

    class_descs = {c["id"]: _class_descriptor(c["id"]) for c in data["class"]}
    prop_descs = {p["id"]: _prop_descriptor(p["id"]) for p in data["property"]}

    unique_class_descs = sorted(set(class_descs.values()))
    unique_prop_descs = sorted(set(prop_descs.values()))
    class_new_id = {desc: str(i) for i, desc in enumerate(unique_class_descs)}
    prop_new_id = {
        desc: str(i + len(unique_class_descs))
        for i, desc in enumerate(unique_prop_descs)
    }

    id_map: dict[str, str] = {}
    for old, desc in class_descs.items():
        id_map[old] = class_new_id[desc]
    for old, desc in prop_descs.items():
        id_map[old] = prop_new_id[desc]
    new_ids = set(id_map.values())

    def _sort_key(value: object) -> tuple[int, object]:
        if isinstance(value, dict):
            return (1, json.dumps(value, sort_keys=True, ensure_ascii=False))
        if isinstance(value, list):
            return (2, json.dumps(value))
        return (0, value)

    def _normalize(value: object) -> object:
        if isinstance(value, str) and value in id_map:
            return id_map[value]
        if isinstance(value, dict):
            return {k: _normalize(v) for k, v in sorted(value.items())}
        if isinstance(value, list):
            items = [_normalize(v) for v in value]
            if items and all(isinstance(x, str) and x in new_ids for x in items):
                return sorted({cast(str, x) for x in items}, key=int)
            return sorted(items, key=_sort_key)
        return value

    data = cast(dict[str, Any], _normalize(data))

    # WIDOCO picks header metadata nondeterministically when many slice
    # ontologies are present; override it from the root ontology source.
    header = data.get("header", {})
    graph = Graph()
    graph.parse(source, format="turtle")
    onto = URIRef(ONTOLOGY_IRI)

    def _first(values: list[str]) -> str | None:
        return values[0] if values else None

    title = _first(
        [str(o) for o in graph.objects(onto, DCTERMS.title)]
        or [str(o) for o in graph.objects(onto, RDFS.label)]
    )
    description = _first(
        [str(o) for o in graph.objects(onto, DCTERMS.description)]
        or [str(o) for o in graph.objects(onto, SKOS.definition)]
        or [str(o) for o in graph.objects(onto, RDFS.comment)]
    )
    authors = [str(o) for o in graph.objects(onto, DCTERMS.creator)] or [
        str(o) for o in graph.objects(onto, DCTERMS.publisher)
    ]
    version = _first([str(o) for o in graph.objects(onto, OWL.versionInfo)])

    if title:
        header["title"] = {"x-gmeow-english": title}
        header["labels"] = {"x-gmeow-english": title}
    if description:
        header["description"] = {"x-gmeow-english": description}
        header["comments"] = {"x-gmeow-english": description}
    if authors:
        header["author"] = authors
    if version:
        header["version"] = version
    header["iri"] = f"{ONTOLOGY_IRI}/"
    data["header"] = dict(sorted(header.items()))

    # Replace OWL2VOWL's nondeterministic numeric counters on anonymous
    # "is a" properties with the stable new ID.
    for prop_attr in data.get("propertyAttribute", []):
        if "iri" not in prop_attr:
            label = prop_attr.get("label", {})
            if isinstance(label, dict) and label.get("IRI-based", "").isdigit():
                label["IRI-based"] = prop_attr["id"]
                prop_attr["label"] = dict(sorted(label.items()))

    path.write_text(
        json.dumps(data, indent=2, sort_keys=True, ensure_ascii=False) + "\n",
        encoding="utf-8",
    )


def _render_webvowl(ctx: _WriteContext, source: Path) -> None:
    """Generate WebVOWL JSON when the WIDOCO image is available."""
    viz_dir = ctx.docs / "visualization"
    viz_dir.mkdir(parents=True, exist_ok=True)

    if not image_available(WIDOCO_IMAGE):
        ctx.write(
            viz_dir / "index.md",
            "# Visualization\n\n"
            "WebVOWL diagram generation requires Docker and the WIDOCO image.\n",
        )
        return

    try:
        run_container(
            WIDOCO_IMAGE,
            [
                "-ontFile",
                _container_path(source),
                "-outFolder",
                _container_path(viz_dir),
                "-rewriteAll",
                "-uniteSections",
                "-includeAnnotationProperties",
                "-noPlaceHolderText",
                "-webVowl",
            ],
            image_workdir=True,
        )
    except Exception as exc:  # pragma: no cover - best-effort optional stage
        logging.exception("WebVOWL generation failed: %s", exc)
        ctx.write(
            viz_dir / "index.md",
            "# Visualization\n\nWebVOWL generation failed; see logs.\n",
        )
        return

    # WIDOCO places the WebVOWL bundle under ``doc/webvowl/``; hoist it so the
    # MkDocs page can reference it directly.
    webvowl_src = viz_dir / "doc" / "webvowl"
    webvowl_dst = viz_dir / "webvowl"
    if webvowl_src.exists():
        if webvowl_dst.exists():
            shutil.rmtree(webvowl_dst)
        shutil.move(str(webvowl_src), str(webvowl_dst))
        shutil.rmtree(viz_dir / "doc")
        _canonicalize_webvowl_json(webvowl_dst / "data" / "ontology.json", source)

    ctx.write(
        viz_dir / "index.md",
        "# Visualization\n\n"
        '<iframe src="webvowl/index.html" width="100%" height="800px">'
        "</iframe>\n",
    )


def _render_oops_report(ctx: _WriteContext, source: Path) -> None:
    """Render OOPS! pitfall report as Markdown, skipping cleanly offline."""
    quality_dir = ctx.docs / "quality"
    quality_dir.mkdir(parents=True, exist_ok=True)
    try:
        report = run_oops(source.read_text(encoding="utf-8"))
        if "something went wrong" in report.lower():
            raise RuntimeError("OOPS! service returned an error response")
        body = f"# OOPS! Pitfall Report\n\n```xml\n{report}\n```\n"
    except Exception as exc:  # pragma: no cover - network best-effort
        logging.warning("OOPS! report unavailable: %s", exc)
        body = (
            "# OOPS! Pitfall Report\n\n"
            "The OOPS! pitfall scan is currently unavailable (network or service "
            f"issue).\n\nDetails: {exc}\n"
        )
    ctx.write(quality_dir / "oops-report.md", body)


def _render_widoco_fragments(ctx: _WriteContext, source: Path) -> None:
    """Extract WIDOCO metadata/changelog/``.htaccess`` when Docker is available."""
    if not image_available(WIDOCO_IMAGE):
        ctx.write(
            ctx.docs / "about.md",
            "# About\n\nWIDOCO-derived provenance metadata requires Docker.\n",
        )
        ctx.write(
            ctx.docs / "changelog.md",
            "# Changelog\n\nWIDOCO-derived changelog requires Docker.\n",
        )
        return

    widoco_dir = ctx.docs / ".widoco-tmp"
    try:
        widoco_dir.mkdir(parents=True, exist_ok=True)
        run_container(
            WIDOCO_IMAGE,
            [
                "-ontFile",
                _container_path(source),
                "-outFolder",
                _container_path(widoco_dir),
                "-rewriteAll",
                "-uniteSections",
                "-includeAnnotationProperties",
                "-noPlaceHolderText",
            ],
            image_workdir=True,
        )

        index_html = widoco_dir / "index-en.html"
        about_text = f"# About\n\nWIDOCO provenance for <{ONTOLOGY_IRI}>.\n"
        if index_html.exists():
            html = index_html.read_text(encoding="utf-8")
            title = "GMEOW"
            if "<title>" in html:
                title = html.split("<title>")[1].split("</title>")[0]
            about_text = f"# About {title}\n\nProvenance and metadata from WIDOCO.\n"
        ctx.write(ctx.docs / "about.md", about_text)

        changelog_html = widoco_dir / "sections" / "changelog-en.html"
        if changelog_html.exists():
            ctx.write(
                ctx.docs / "changelog.md",
                "# Changelog\n\n" + changelog_html.read_text(encoding="utf-8") + "\n",
            )
        else:
            ctx.write(
                ctx.docs / "changelog.md",
                "# Changelog\n\nNo changelog available.\n",
            )

        htaccess = widoco_dir / ".htaccess"
        if htaccess.exists():
            ctx.write(ctx.docs / ".htaccess", htaccess.read_text(encoding="utf-8"))
    except Exception as exc:  # pragma: no cover - optional Docker stage
        ctx.write(ctx.docs / "about.md", f"# About\n\nWIDOCO run failed: {exc}\n")
        ctx.write(
            ctx.docs / "changelog.md",
            f"# Changelog\n\nWIDOCO run failed: {exc}\n",
        )
    finally:
        if widoco_dir.exists():
            shutil.rmtree(widoco_dir)


