@register
class OntologyDocsGenerator(Generator):
    """Emit the committed ontology-docs site at the repository root."""

    name: str = "ontology-docs"
    is_directory_output: bool = True

    @property
    def inputs(self) -> Sequence[Path]:
        """Canonical sources that drive the docs site."""
        return [
            PROJECT_ROOT / "ontology" / "gmeow.ttl",
            *iter_module_files(),
            STATEMENT_RDF12_FILE,
            *sorted(SLICES_DIR.glob("*/*/manifest.ttl")),
            *sorted(SLICES_DIR.glob("*/*/docs.md")),
        ]

    @property
    def outputs(self) -> Sequence[Path]:
        """The committed ontology-docs tree (declared recursively)."""
        return [PROJECT_ROOT / "ontology-docs"]

    def render(self, staging: Path) -> None:
        """Render the site into the staging tree."""
        src_hash = getattr(self, "_source_hash", "")
        build_ontology_docs(staging / "ontology-docs", source_hash=src_hash)

    def compare(self, fresh: Path, committed: Path) -> list[str]:
        """Directory-aware drift comparison."""
        try:
            rel_root = str(committed.relative_to(PROJECT_ROOT))
        except ValueError:
            rel_root = committed.name

        if not committed.exists():
            return [f"{rel_root} (missing committed directory)"]
        if not fresh.exists():
            return [f"{rel_root} (not produced in staging)"]

        def _rel(path: Path) -> str:
            try:
                return str(path.relative_to(PROJECT_ROOT))
            except ValueError:
                return str(path)

        problems: list[str] = []
        fresh_files = {p.relative_to(fresh) for p in fresh.rglob("*") if p.is_file()}
        committed_files = {
            p.relative_to(committed) for p in committed.rglob("*") if p.is_file()
        }

        for rel in sorted(committed_files - fresh_files):
            problems.append(f"{_rel(committed / rel)} (missing in fresh)")
        for rel in sorted(fresh_files - committed_files):
            problems.append(f"{_rel(committed / rel)} (missing in committed)")
        for rel in sorted(fresh_files & committed_files):
            fresh_bytes = (fresh / rel).read_bytes()
            committed_bytes = (committed / rel).read_bytes()
            if fresh_bytes != committed_bytes:
                problems.append(f"{_rel(committed / rel)}")

        return problems
